//! S6-T4 ruling 4: lexical format v3 against the indexes written before it.
//! The fixture `tests/fixtures/index-98c4a2b/` is `fixtures/family-folder/home`
//! indexed with `--filename-index` by `main` at 98c4a2b (manifest v2.2, the
//! content lexical section `HYBLEX02`, the file-name one `HYBLEX01`),
//! regenerated by `tests/fixtures/gen_index_98c4a2b.sh`. It must open and
//! answer under this library exactly as a fresh v3 index of the same folder;
//! its first update publishes v3 and still answers the same; a crash
//! between writing and publishing leaves one whole generation, v2 or v3.
//! The other way round, `tests/fixtures/index-v3-s6t4/` (this writer's
//! output for the same folder) is refused by 98c4a2b's manifest check, here
//! reproduced (`refusedBy98c4a2b`; the run of that commit's own binary and
//! library is in `docs/evidence/s6-t4/old-library-on-v3.txt`).
const std = @import("std");
const apply = @import("apply.zig");
const cli = @import("cli.zig");
const engine_module = @import("engine.zig");
const filename_field = @import("filename_field.zig");
const lexical_segment = @import("lexical_segment.zig");
const manifest = @import("manifest.zig");
const ops = @import("ops.zig");
const publication = @import("publication.zig");
const snapshot_open = @import("snapshot_open.zig");

const io = std.testing.io;
const fixture_v2 = "../tests/fixtures/index-98c4a2b";
const fixture_v3 = "../tests/fixtures/index-v3-s6t4";
const folder = "../fixtures/family-folder/home";
const files = [_][]const u8{ "MANIFEST", "INDEX-STATE.json", "documents-1.hybseg", "lexical-1.hyblex", "source-1.hybsrc", "state-1.hybstate", "filenames-1.hybseg", "filename-lexical-1.hyblex" };

const queries = [_][]const u8{ "hedgehogs pond", "frogspawn", "garden", "family of snails", "lock", "the", "birthday cake", "பள்ளி", "budget", "recipes soup", "chores rota", "trip" };
const find_modes = [_][]const u8{ "words", "phrase", "prefix" };
const read_files = [_][]const u8{ "garden.md", "tamil-notes.md", "bills.txt", "crlf-shopping.md" };

fn copyFixture(a: std.mem.Allocator, from_path: []const u8, out: std.Io.Dir) !void {
    var from = try std.Io.Dir.cwd().openDir(io, from_path, .{});
    defer from.close(io);
    for (files) |name| try out.writeFile(io, .{ .sub_path = name, .data = try from.readFileAlloc(io, name, a, .unlimited) });
}

fn tmpPath(a: std.mem.Allocator, tmp: std.testing.TmpDir, sub: []const u8) ![]const u8 {
    return std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/{s}", .{ tmp.sub_path, sub });
}

fn params(a: std.mem.Allocator, text: []const u8) !std.json.ObjectMap {
    return switch (try ops.parseObject(a, text)) {
        .ok => |map| map,
        .failed => error.TestUnexpectedResult,
    };
}

fn okJson(result: ops.Result) ![]const u8 {
    return switch (result) {
        .ok => |json| json,
        .failed => |failure| {
            std.debug.print("S6-T4 compat: refused: {s}\n", .{failure.message});
            return error.TestUnexpectedResult;
        },
    };
}

/// Every answer the tests compare, one per line: `query` (text and JSON)
/// and `evidence` on all three fields, `find` in its three modes, `outline`
/// and `read_span` of four files, `list_files`, `roots` and `index_status`.
fn answers(a: std.mem.Allocator, dir: std.Io.Dir) ![]const []const u8 {
    var out = std.ArrayList([]const u8).empty;
    for ([_]filename_field.Field{ .content, .filename, .both }) |field| {
        const engine = if (field != .content) (try snapshot_open.openScoped(a, io, dir)).engine else try snapshot_open.open(a, io, dir);
        for (queries) |query| {
            for ([_]bool{ false, true }) |json| {
                var output: std.Io.Writer.Allocating = .init(a);
                try cli.answerQuery(a, engine, query, .{ .search_field = field, .top_k = 5, .json = json }, &output.writer);
                try out.append(a, output.written());
            }
            var output: std.Io.Writer.Allocating = .init(a);
            try cli.answerEvidence(a, engine, query, .{ .search_field = field, .top_k = 5 }, &output.writer);
            try out.append(a, output.written());
        }
    }
    const opened = try snapshot_open.openScoped(a, io, dir);
    defer opened.folder.close();
    const service = @import("service.zig").Service{ .engine = opened.engine, .folder = opened.folder };
    for (queries) |query| for (find_modes) |mode| {
        try out.append(a, try okJson(try ops.find(a, service, try params(a, try std.fmt.allocPrint(a, "{{\"query\":\"{s}\",\"mode\":\"{s}\"}}", .{ query, mode })), cli.cli_caller)));
    };
    for (read_files) |path| {
        try out.append(a, try okJson(try ops.outline(a, service, try params(a, try std.fmt.allocPrint(a, "{{\"root_id\":\"r-legacy\",\"path\":\"{s}\"}}", .{path})), cli.cli_caller)));
        try out.append(a, try okJson(try ops.readSpan(a, service, try params(a, try std.fmt.allocPrint(a, "{{\"root_id\":\"r-legacy\",\"path\":\"{s}\",\"start_line\":1,\"end_line\":4}}", .{path})), cli.cli_caller)));
    }
    try out.append(a, try okJson(try ops.listFiles(a, service, try params(a, "{}"), cli.cli_caller)));
    try out.append(a, try okJson(try ops.visibleRoots(a, service, try params(a, "{}"), cli.cli_caller)));
    try out.append(a, try okJson(try ops.indexStatus(a, service, try params(a, "{}"), cli.cli_caller)));
    return out.items;
}

/// `text` with the number after every `"generation":`, `generation ` and
/// `"next_cursor":"` (a cursor is `<generation>:<offset>`) replaced by `N`:
/// an update publishes the next generation number, and the answers name it.
fn withoutGeneration(a: std.mem.Allocator, text: []const u8) ![]const u8 {
    var out = std.ArrayList(u8).empty;
    var at: usize = 0;
    while (at < text.len) {
        var matched: ?usize = null;
        for ([_][]const u8{ "\"generation\":", "generation ", "\"next_cursor\":\"" }) |key| {
            if (std.mem.startsWith(u8, text[at..], key)) matched = key.len;
        }
        if (matched) |len| {
            try out.appendSlice(a, text[at..][0..len]);
            at += len;
            if (at < text.len and std.ascii.isDigit(text[at])) {
                while (at < text.len and std.ascii.isDigit(text[at])) at += 1;
                try out.append(a, 'N');
            }
        } else {
            try out.append(a, text[at]);
            at += 1;
        }
    }
    return out.items;
}

/// Equal answers, the generation number aside (`withoutGeneration`).
fn expectSameAnswers(want: []const []const u8, got: []const []const u8) !void {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const a = arena_state.allocator();
    try std.testing.expectEqual(want.len, got.len);
    for (want, got, 0..) |want_raw, got_raw, i| {
        const w = try withoutGeneration(a, want_raw);
        const g = try withoutGeneration(a, got_raw);
        if (!std.mem.eql(u8, w, g)) {
            const first = std.mem.indexOfDiff(u8, w, g).?;
            const from = first -| 200;
            std.debug.print("S6-T4 compat: answer {d} differs at byte {d}:\n{s}\n---\n{s}\n", .{ i, first, w[from..@min(w.len, first + 200)], g[from..@min(g.len, first + 200)] });
            return error.TestExpectedEqual;
        }
    }
}

/// A fresh index of `folder` written by this library (v3), at `sub`.
fn freshIndex(a: std.mem.Allocator, tmp: std.testing.TmpDir, sub: []const u8) !std.Io.Dir {
    var sink: std.Io.Writer.Allocating = .init(a);
    try cli.runIndex(io, a, folder, try tmpPath(a, tmp, sub), .{ .caps = .{ .filename_index = true } }, &sink.writer);
    return tmp.dir.openDir(io, sub, .{ .iterate = true });
}

fn magicOf(a: std.mem.Allocator, dir: std.Io.Dir, name: []const u8) ![]const u8 {
    return (try dir.readFileAlloc(io, name, a, .unlimited))[0..8];
}

fn expectV3(a: std.mem.Allocator, dir: std.Io.Dir) !manifest.Manifest {
    const metadata = try manifest.decode(try dir.readFileAlloc(io, publication.current_manifest_file, a, .unlimited));
    try std.testing.expect(metadata.lexical_v3);
    try std.testing.expectEqualStrings(lexical_segment.magic_v3, try magicOf(a, dir, metadata.lexical_file));
    try std.testing.expectEqualStrings(lexical_segment.magic_v3, try magicOf(a, dir, metadata.filename.?.lexical_file));
    return metadata;
}

test "S6-T4 ruling 4: the 98c4a2b fixture is the format before v3 (HYBLEX02 content, HYBLEX01 file names, no flag 5)" {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const a = arena_state.allocator();
    var dir = try std.Io.Dir.cwd().openDir(io, fixture_v2, .{});
    defer dir.close(io);
    const metadata = try manifest.decode(try dir.readFileAlloc(io, publication.current_manifest_file, a, .unlimited));
    try std.testing.expect(!metadata.lexical_v3);
    try std.testing.expect(metadata.xxh3_sections and metadata.filename != null and metadata.state != null);
    try std.testing.expectEqualStrings(lexical_segment.magic_v2, try magicOf(a, dir, metadata.lexical_file));
    try std.testing.expectEqualStrings(lexical_segment.magic, try magicOf(a, dir, metadata.filename.?.lexical_file));
}

test "S6-T4 ruling 4: a 98c4a2b (v2) index opens and answers exactly as a fresh v3 index of the same folder" {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const a = arena_state.allocator();
    var tmp = std.testing.tmpDir(.{ .iterate = true });
    defer tmp.cleanup();
    try tmp.dir.createDir(io, "old", .default_dir);
    var old = try tmp.dir.openDir(io, "old", .{ .iterate = true });
    defer old.close(io);
    try copyFixture(a, fixture_v2, old);
    var fresh = try freshIndex(a, tmp, "fresh");
    defer fresh.close(io);
    _ = try expectV3(a, fresh);
    const want = try answers(a, fresh);
    try std.testing.expect(want.len > 150);
    try expectSameAnswers(want, try answers(a, old));
}

test "S6-T4 ruling 4: the first update of a v2 index publishes v3 (both lexical sections) and answers as a fresh index" {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const a = arena_state.allocator();
    var tmp = std.testing.tmpDir(.{ .iterate = true });
    defer tmp.cleanup();
    try tmp.dir.createDir(io, "old", .default_dir);
    var old = try tmp.dir.openDir(io, "old", .{ .iterate = true });
    defer old.close(io);
    try copyFixture(a, fixture_v2, old);
    // The same folder unchanged: `index --update` re-reads every file, finds
    // none changed and still publishes generation 2, which is v3 (the
    // content section re-encoded from the decoded v2 one, the file-name
    // section rebuilt once).
    var sink: std.Io.Writer.Allocating = .init(a);
    try cli.runIndex(io, a, folder, try tmpPath(a, tmp, "old"), .{ .update = true }, &sink.writer);
    const metadata = try expectV3(a, old);
    try std.testing.expectEqual(@as(u64, 2), metadata.generation);
    var fresh = try freshIndex(a, tmp, "fresh");
    defer fresh.close(io);
    try expectSameAnswers(try answers(a, fresh), try answers(a, old));
    // The v3 sections are a fresh index's, byte for byte.
    const fresh_metadata = try manifest.decode(try fresh.readFileAlloc(io, publication.current_manifest_file, a, .unlimited));
    try std.testing.expectEqualSlices(u8, try fresh.readFileAlloc(io, fresh_metadata.lexical_file, a, .unlimited), try old.readFileAlloc(io, metadata.lexical_file, a, .unlimited));
    try std.testing.expectEqualSlices(u8, try fresh.readFileAlloc(io, fresh_metadata.filename.?.lexical_file, a, .unlimited), try old.readFileAlloc(io, metadata.filename.?.lexical_file, a, .unlimited));
    // A second update (a new file) publishes v3 again.
    const request =
        \\{"changes":[{"op":"add","root_id":"r-legacy","path":"shed.txt","content_base64":"VGhlIHNoZWQgbmVlZHMgYSBuZXcgbG9jay4K"}]}
    ;
    _ = switch (try apply.applyChanges(a, io, old, request, .{})) {
        .ok => |r| r,
        .failed => return error.TestUnexpectedResult,
    };
    const third = try expectV3(a, old);
    try std.testing.expectEqual(@as(u64, 3), third.generation);
    try std.testing.expect(third.filename.?.file_count == metadata.filename.?.file_count + 1);
}

test "S6-T4 ruling 4: a crash between writing and publishing leaves the whole v2 generation, or after the manifest the whole v3 one" {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const a = arena_state.allocator();
    var tmp = std.testing.tmpDir(.{ .iterate = true });
    defer tmp.cleanup();
    for ([_][]const u8{ "before", "after", "v2" }) |name| try tmp.dir.createDir(io, name, .default_dir);
    var before = try tmp.dir.openDir(io, "before", .{ .iterate = true });
    defer before.close(io);
    var after = try tmp.dir.openDir(io, "after", .{ .iterate = true });
    defer after.close(io);
    var v2 = try tmp.dir.openDir(io, "v2", .{ .iterate = true });
    defer v2.close(io);
    for ([_]std.Io.Dir{ before, after, v2 }) |dir| try copyFixture(a, fixture_v2, dir);
    const want_v2 = try answers(a, v2);
    const request =
        \\{"changes":[{"op":"add","root_id":"r-legacy","path":"shed.txt","content_base64":"VGhlIHNoZWQgbmVlZHMgYSBuZXcgbG9jay4K"}]}
    ;
    // After the manifest is replaced (the writer's own crash hook): the v3
    // generation is whole and current.
    try std.testing.expectError(error.SimulatedCrash, apply.applyChanges(a, io, after, request, .{ .fail_after_publish = true }));
    const published = try expectV3(a, after);
    try std.testing.expectEqual(@as(u64, 2), published.generation);
    const v3_answers = try answers(a, after);
    // Before the manifest: every section of generation 2 written and linked
    // (the files the crashed publish left), `MANIFEST` still generation 1.
    var listing = after.iterate();
    while (try listing.next(io)) |entry| {
        if (std.mem.indexOf(u8, entry.name, "-2.") == null) continue;
        try before.writeFile(io, .{ .sub_path = entry.name, .data = try after.readFileAlloc(io, entry.name, a, .unlimited) });
    }
    const still = try manifest.decode(try before.readFileAlloc(io, publication.current_manifest_file, a, .unlimited));
    try std.testing.expectEqual(@as(u64, 1), still.generation);
    try std.testing.expect(!still.lexical_v3);
    try expectSameAnswers(want_v2, try answers(a, before));
    // The next update over the leftovers publishes a whole v3 generation
    // that answers as the crashed one did.
    _ = switch (try apply.applyChanges(a, io, before, request, .{})) {
        .ok => |r| r,
        .failed => return error.TestUnexpectedResult,
    };
    // (generation 3: the leftover number 2 is not reused).
    try std.testing.expectEqual(@as(u64, 3), (try expectV3(a, before)).generation);
    try expectSameAnswers(v3_answers, try answers(a, before));
}

/// 98c4a2b's manifest check (`manifest.decodeV2`, the first thing every
/// open and every writer does with the current generation): magic, version
/// 2, then any flag outside bits 0-4 is `UnsupportedFlags`, before a field
/// past the flags or any section is read.
fn refusedBy98c4a2b(manifest_bytes: []const u8) bool {
    const known_flags_98c4a2b: u16 = 0x1f;
    if (manifest_bytes.len < 12 or !std.mem.eql(u8, manifest_bytes[0..8], "HYBMAN02")) return false;
    if (std.mem.readInt(u16, manifest_bytes[8..10], .little) != 2) return false;
    return std.mem.readInt(u16, manifest_bytes[10..12], .little) & ~known_flags_98c4a2b != 0;
}

test "S6-T4 ruling 4: a library before v3 refuses a v3 index at the manifest's flags (UnsupportedFlags), never reading a section" {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const a = arena_state.allocator();
    var committed = try std.Io.Dir.cwd().openDir(io, fixture_v3, .{});
    defer committed.close(io);
    const committed_manifest = try committed.readFileAlloc(io, publication.current_manifest_file, a, .unlimited);
    try std.testing.expect(refusedBy98c4a2b(committed_manifest));
    try std.testing.expectEqual(manifest.flag_lexical_v3, std.mem.readInt(u16, committed_manifest[10..12], .little) & ~@as(u16, 0x1f));
    var v2 = try std.Io.Dir.cwd().openDir(io, fixture_v2, .{});
    defer v2.close(io);
    try std.testing.expect(!refusedBy98c4a2b(try v2.readFileAlloc(io, publication.current_manifest_file, a, .unlimited)));
    // The committed v3 fixture is what this writer gives the same folder,
    // byte for byte (so it stays the format's reference), and it reads.
    var tmp = std.testing.tmpDir(.{ .iterate = true });
    defer tmp.cleanup();
    var fresh = try freshIndex(a, tmp, "fresh");
    defer fresh.close(io);
    for (files) |name| {
        if (std.mem.eql(u8, name, "INDEX-STATE.json")) continue;
        try std.testing.expectEqualSlices(u8, try committed.readFileAlloc(io, name, a, .unlimited), try fresh.readFileAlloc(io, name, a, .unlimited));
    }
    try std.testing.expect(refusedBy98c4a2b(try fresh.readFileAlloc(io, publication.current_manifest_file, a, .unlimited)));
    _ = try expectV3(a, committed);
}

fn uleb(bytes: []const u8, at: *usize) u64 {
    var value: u64 = 0;
    var shift: u6 = 0;
    while (true) {
        const byte = bytes[at.*];
        at.* += 1;
        value |= @as(u64, byte & 0x7f) << shift;
        if (byte & 0x80 == 0) return value;
        shift += 7;
    }
}

test "S6-T4 ruling 3: two terms sharing 300 bytes go through the analyzer, the writer caps the shared prefix at 255, and each finds its own file" {
    // The analyzers have no term-length limit (a token is a maximal run of
    // letters and digits), so a 310-byte word is one term.
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const a = arena_state.allocator();
    var tmp = std.testing.tmpDir(.{ .iterate = true });
    defer tmp.cleanup();
    const stem = "q" ** 300;
    const word_a = stem ++ "a" ** 10;
    const word_b = stem ++ "b" ** 10;
    try tmp.dir.createDirPath(io, "folder");
    try tmp.dir.writeFile(io, .{ .sub_path = "folder/a.md", .data = "The long word " ++ word_a ++ " is here.\n" });
    try tmp.dir.writeFile(io, .{ .sub_path = "folder/b.md", .data = "The long word " ++ word_b ++ " is here.\n" });
    var sink: std.Io.Writer.Allocating = .init(a);
    try cli.runIndex(io, a, try tmpPath(a, tmp, "folder"), try tmpPath(a, tmp, "out"), .{ .caps = .{ .filename_index = true } }, &sink.writer);
    var out = try tmp.dir.openDir(io, "out", .{ .iterate = true });
    defer out.close(io);
    const metadata = try expectV3(a, out);
    // Walk the content section's dictionary: the entry after `word_a` shares
    // 255 bytes (not 300) and carries the other 55 as its suffix.
    const bytes = try out.readFileAlloc(io, metadata.lexical_file, a, .unlimited);
    const header = try lexical_segment.inspect(bytes);
    var at = header.length() + header.document_lengths_bytes;
    const end = at + header.dictionary_bytes;
    var previous = std.ArrayList(u8).empty;
    var capped: usize = 0;
    while (at < end) {
        const shared: usize = @intCast(uleb(bytes, &at));
        const suffix_length: usize = @intCast(uleb(bytes, &at));
        const suffix = bytes[at..][0..suffix_length];
        at += suffix_length;
        _ = uleb(bytes, &at); // document frequency
        _ = uleb(bytes, &at); // list bytes
        try std.testing.expect(shared <= lexical_segment.max_shared_v3 and shared <= previous.items.len);
        previous.shrinkRetainingCapacity(shared);
        try previous.appendSlice(a, suffix);
        if (std.mem.eql(u8, previous.items, word_b)) {
            try std.testing.expectEqual(@as(usize, 255), shared);
            try std.testing.expectEqual(@as(usize, 55), suffix_length);
            capped += 1;
        }
    }
    try std.testing.expectEqual(@as(usize, 1), capped);
    // Each word finds its own file and only it, by query and by find.
    const opened = try snapshot_open.openScoped(a, io, out);
    defer opened.folder.close();
    const service = @import("service.zig").Service{ .engine = opened.engine, .folder = opened.folder };
    for ([_]struct { []const u8, []const u8, []const u8 }{ .{ word_a, "a.md", "b.md" }, .{ word_b, "b.md", "a.md" } }) |case| {
        var output: std.Io.Writer.Allocating = .init(a);
        try cli.answerQuery(a, try snapshot_open.open(a, io, out), case[0], .{ .top_k = 5, .json = true }, &output.writer);
        try std.testing.expect(std.mem.indexOf(u8, output.written(), case[1]) != null);
        try std.testing.expect(std.mem.indexOf(u8, output.written(), case[2]) == null);
        const found = try okJson(try ops.find(a, service, try params(a, try std.fmt.allocPrint(a, "{{\"query\":\"{s}\"}}", .{case[0]})), cli.cli_caller));
        try std.testing.expect(std.mem.indexOf(u8, found, case[1]) != null);
        try std.testing.expect(std.mem.indexOf(u8, found, case[2]) == null);
    }
}

/// `dir`'s manifest rewritten with `lexical_v3` set to `value` (its own
/// checksum recomputed, so only the flag-against-section rule can refuse it).
fn rewriteLexicalFlag(a: std.mem.Allocator, dir: std.Io.Dir, value: bool) !manifest.Manifest {
    var metadata = try manifest.decode(try dir.readFileAlloc(io, publication.current_manifest_file, a, .unlimited));
    metadata.lexical_v3 = value;
    const bytes = try manifest.encode(metadata, try a.alloc(u8, 4096));
    try dir.writeFile(io, .{ .sub_path = publication.current_manifest_file, .data = bytes });
    return metadata;
}

test "S6-T4 ruling 4: manifest bit 5 and the lexical sections must agree (a v3 section without the flag, a v2 one with it, a v1 file-name section under it)" {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const a = arena_state.allocator();
    var tmp = std.testing.tmpDir(.{ .iterate = true });
    defer tmp.cleanup();
    for ([_][]const u8{ "v3-unflagged", "v2-flagged", "mixed" }) |name| try tmp.dir.createDir(io, name, .default_dir);
    // HYBLEX03 sections under a manifest without bit 5.
    var unflagged = try tmp.dir.openDir(io, "v3-unflagged", .{ .iterate = true });
    defer unflagged.close(io);
    try copyFixture(a, fixture_v3, unflagged);
    _ = try rewriteLexicalFlag(a, unflagged, false);
    try std.testing.expectError(error.InvalidLexicalSection, snapshot_open.open(a, io, unflagged));
    try std.testing.expectError(error.InvalidLexicalSection, snapshot_open.openScoped(a, io, unflagged));
    // HYBLEX02/HYBLEX01 sections under a manifest with bit 5.
    var flagged = try tmp.dir.openDir(io, "v2-flagged", .{ .iterate = true });
    defer flagged.close(io);
    try copyFixture(a, fixture_v2, flagged);
    _ = try rewriteLexicalFlag(a, flagged, true);
    try std.testing.expectError(error.InvalidLexicalSection, snapshot_open.open(a, io, flagged));
    try std.testing.expectError(error.InvalidLexicalSection, snapshot_open.openScoped(a, io, flagged));
    // A v3 content section with bit 5, but the file-name section is the
    // 98c4a2b one (`HYBLEX01`, its length and checksum recorded).
    var mixed = try tmp.dir.openDir(io, "mixed", .{ .iterate = true });
    defer mixed.close(io);
    try copyFixture(a, fixture_v3, mixed);
    var v2 = try std.Io.Dir.cwd().openDir(io, fixture_v2, .{});
    defer v2.close(io);
    const old_names = try v2.readFileAlloc(io, "filename-lexical-1.hyblex", a, .unlimited);
    try mixed.writeFile(io, .{ .sub_path = "filename-lexical-1.hyblex", .data = old_names });
    var metadata = try manifest.decode(try mixed.readFileAlloc(io, publication.current_manifest_file, a, .unlimited));
    metadata.filename.?.lexical_bytes = old_names.len;
    metadata.filename.?.lexical_checksum = (try lexical_segment.inspect(old_names)).checksum;
    try mixed.writeFile(io, .{ .sub_path = publication.current_manifest_file, .data = try manifest.encode(metadata, try a.alloc(u8, 4096)) });
    const catalog = try mixed.readFileAlloc(io, metadata.filename.?.catalog_file, a, .unlimited);
    try std.testing.expectError(error.InvalidFilenameLexicalSection, manifest.validateFilenameSections(metadata, catalog, old_names));
    // The eager open (it loads the file-name sections) refuses it; the
    // scoped open refuses it at the first file-name query, which loads them.
    try std.testing.expectError(error.InvalidFilenameLexicalSection, snapshot_open.open(a, io, mixed));
    if (snapshot_open.openScoped(a, io, mixed)) |opened| {
        defer opened.folder.close();
        try std.testing.expectError(error.InvalidFilenameLexicalSection, opened.engine.queryFields(a, "garden", .filename, .{ .top_k = 3, .retrieval_mode = .lexical }));
    } else |err| try std.testing.expectEqual(error.InvalidFilenameLexicalSection, err);
}

test "S6-T4: import-json with the file-name channel writes what 98c4a2b wrote (manifest without bit 5, HYBLEX01 sections), byte for byte" {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const a = arena_state.allocator();
    const imported_98c4a2b = "../tests/fixtures/import-filename-98c4a2b";
    var want = try std.Io.Dir.cwd().openDir(io, imported_98c4a2b, .{});
    defer want.close(io);
    var tmp = std.testing.tmpDir(.{ .iterate = true });
    defer tmp.cleanup();
    _ = try @import("importer.zig").importJson(tmp.dir, io, a, try want.readFileAlloc(io, "interchange.json", a, .unlimited));
    for ([_][]const u8{ "MANIFEST", "documents-1.hybseg", "lexical-1.hyblex", "filenames-1.hybseg", "filename-lexical-1.hyblex" }) |name| {
        try std.testing.expectEqualSlices(u8, try want.readFileAlloc(io, name, a, .unlimited), try tmp.dir.readFileAlloc(io, name, a, .unlimited));
    }
    const metadata = try manifest.decode(try tmp.dir.readFileAlloc(io, publication.current_manifest_file, a, .unlimited));
    try std.testing.expect(!metadata.lexical_v3 and metadata.filename != null);
    try std.testing.expectEqualStrings(lexical_segment.magic, try magicOf(a, tmp.dir, metadata.filename.?.lexical_file));
    // It opens and answers a file-name query under this library.
    const opened = try snapshot_open.openScoped(a, io, tmp.dir);
    defer opened.folder.close();
    try std.testing.expect((try opened.engine.queryFields(a, "budget", .filename, .{ .top_k = 3, .retrieval_mode = .lexical })).len > 0);
}
